"""Basketball units 6-10: situational, rules, analytics, scouting and development. Two question types per objective.

The analytics and situational units are arithmetic and are recomputed by the verifier. Rules cards name the level and
print any figure the rules articles themselves would settle, since only the 2025-26 rules-changes document and the
book's table of contents were read; FIBA and NBA figures are general knowledge and are flagged in the standard's note.
"""
from opl_dsl import Q

FILE, FRAMEWORK, PRACTICE = "bb-core-1", "basketball", "P1"
MC = ["{{o1}}", "{{o2}}", "{{o3}}", "{{o4}}"]
SI, RU, AN, SC, DE = "bb.situational", "bb.rules", "bb.analytics", "bb.scouting", "bb.development"


def facts(name, skill, rows, explain):
    return Q(name, skill, "{{q}}", pace="recall",
             cases=[{"q": q, "o1": a, "o2": b, "o3": c, "o4": d} for q, a, b, c, d in rows],
             choice=MC, correct="0", verify="authored", explain=explain)


